verus! {
    // replace_chars: for each position i, if s[i] == old then result[i] == new, else result[i] == s[i]
    fn replace_chars(s: &[char], old: char, new: char) -> (result: Vec<char>)
        ensures
            // same length
            result.len() == s.len(),
            // pointwise replacement property
            forall|i: int|
                0 <= i && i < result.len() ==>
                    result[i] == (if s[i] == old { new } else { s[i] }),
    {
        let mut result: Vec<char> = Vec::new();
        let mut i: int = 0;
        // iterate i from 0 to s.len()
        while i < s.len()
            invariant
                // bounds on i
                0 <= i && i <= s.len(),
                // result has grown exactly to length i
                result.len() == i,
                // for all processed positions j < i, the replacement property holds
                forall|j: int|
                    0 <= j && j < i ==>
                        result[j] == (if s[j] == old { new } else { s[j] }),
            decreases
                // we make progress toward s.len()
                s.len() - i,
        {
            // compute the replacement character for position i
            let c  = s[i];
            let c2 = if c == old { new } else { c };

            // advance the index
            i = i + 1;
            // push the newly computed character
            result.push(c2);

            // now result.len() == i
            assert(result.len() == i);

            // and at the new position i-1 it satisfies the replacement property
            assert(
                result[i - 1]
                    == (if s[i - 1] == old { new } else { s[i - 1] })
            );
        }
        result
    }
}

